/* ============================================================
   CONTENIDO DE LOS 7 DOCUMENTOS DEL EXPEDIENTE
   Cada documento es una lista de bloques (título, párrafo, lista,
   tabla, firmas). La misma lista se usa para la vista previa, el
   Word y el PDF, así los tres salen siempre iguales.
   Textos tomados del expediente original (ABOGADO.docx, 2026).
   ============================================================ */

/* --- piezas de texto ---
   'texto'            texto normal
   b('texto')         negrilla
   x(valor,'nombre')  dato que llena el software (si falta, se marca en rojo)
   xb(valor,'nombre') dato en negrilla                                        */
const b=s=>({s:String(s),b:1});
/* De qué casilla sale cada dato: así "✎ Editar" lleva al lugar correcto.
   Casilla del formulario, 'cat:campo' (Catálogo) o 'aj:campo' (Ajustes). */
const FX={'nombre del contratista':'nombre','nombre':'nombre','documento':'ndoc','No. CDP':'cdp','fecha del CDP':'fcdp','No. RP':'rp','rubro':'cat:rubro','nombre del rubro':'cat:rubroNombre','objeto':'cat:objeto','meses':'meses','cuota':'valor','valor':'valor','plazo':'plazo','fecha de necesidad':'fnec','fecha de suscripción':'fsus','año':'fsus','No. contrato':'consec','forma de pago':'pagot','necesidad':'cat:necesidad','conveniencia':'cat:conveniencia','consideraciones':'cat:consideraciones','alcances':'cat:alcances','obligaciones':'cat:obligaciones','idoneidad':'cat:idoneidad','supervisor':'cat:supervisor','subgerente administrativa':'aj:supAdm','gerente':'aj:gerente'};
const x=(val,lbl,bold)=>{const f=FX[lbl]||'',l=lbl||'';return(val||val===0)&&String(val).trim()!==''?{s:String(val),v:1,b:bold?1:0,f,l}:{s:'falta: '+lbl,m:1,f,l}};
const xb=(val,lbl)=>x(val,lbl,1);
/* --- bloques --- */
const TIT=(...c)=>({k:'tit',c});                 // título centrado en negrilla
const SEC=(...c)=>({k:'sec',c});                 // subtítulo de sección
const P=(...c)=>({k:'p',c});                     // párrafo justificado
const PC=(...c)=>({k:'p',c,al:'c'});             // párrafo centrado
const PI=(...c)=>({k:'p',c,al:'l'});             // párrafo a la izquierda
const UL=items=>({k:'ul',items});                // lista con viñetas
const TBL=(rows,w,o={})=>({k:'tbl',rows,w,...o}); // tabla: w = anchos en %
const FIR=(...cols)=>({k:'fir',cols});           // bloque de firmas
const NOTA=(...c)=>({k:'p',c,al:'l',small:1});   // texto pequeño

const DOCLIST=[['nec','Necesidad'],['est','Estudios previos'],['ido','Idoneidad'],['des','Designación'],['not','Notificación'],['con','Contrato'],['act','Acta de inicio']];

function bloques(k,c){
 const E=AJ.entidad,M=AJ.municipio,Dp=AJ.depto,obj=xb(c.p.objeto,'objeto'),anio=x(c.anio,'año');
 const pago=String(S.pagot||'').trim()?[x(String(S.pagot).trim(),'forma de pago')]:[x(c.cuotasL,'meses'),' cuotas mensuales iguales por valor de ',x(c.cuotaL,'cuota')];
 const cdp=['CERTIFICADO DE DISPONIBILIDAD PRESUPUESTAL – CDP No. ',xb(S.cdp,'No. CDP'),' del ',x(c.fcdpC,'fecha del CDP'),' Rubro No. ',x(c.p.rubro,'rubro'),', con Nombre: ',x(c.p.rubroNombre,'nombre del rubro')];
 const persona=[c.tr.sr,' ',xb(S.nombre,'nombre del contratista'),', ',c.tr.id,' con ',x(c.doc,'documento')];
 const ob=c.obl.map(t=>c.p.obligaciones.includes(t)?[x(t,'obligaciones')]:[t]);
 const supFirma=[[xb(c.sup.n,'supervisor')],[c.sup.c]];
 switch(k){

 case 'nec':return[
  TIT('REQUERIMIENTO DE NECESIDAD Y/O ESTUDIO DE NECESIDAD'),
  P('Que la ',E,' en cabeza de la Gerente, imparte siempre todas las gestiones pertinentes para el curso natural de las funciones de la entidad.'),
  P('Dicho lo expuesto, se procede a la verificación del personal adscrito a la planta global de la entidad, avizorando que no existe el personal suficiente para desarrollar a cabalidad todas las dimensiones estructuradas sin que interrumpan con el curso normal de sus obligaciones y funcionamiento administrativo, asistencial u operativo de la entidad.'),
  P('Es así que en esta oportunidad se requiere contratar una persona natural o jurídica que imparta la ',obj),
  P('El anterior personal y/o servicio es requerido para el cumplimiento de las obligaciones legales establecidas, garantizando los fines legales pertinentes.'),
  P('Queda constancia que la necesidad planteada se suscribió el día ',x(c.fnecL,'fecha de necesidad'),'.'),
  FIR([[xb(AJ.supAdm,'subgerente administrativa')],[AJ.supAdmCargo]])];

 case 'est':return[
  TIT('ESTUDIOS PREVIOS'),
  P('La ',E,', ha determinado la necesidad de adelantar los estudios previos que conducen a la celebración de un contrato de ',obj,' Con sujeción del Decreto 1082 del 26 de mayo de 2015 y del ',AJ.manual,' por medio del cual se adopta el Manual de Contratación.'),
  SEC('1. DESCRIPCIÓN DE LA NECESIDAD'),
  ...c.p.necesidad.map(t=>P(x(t,'necesidad'))),
  SEC('2. JUSTIFICACIÓN DE LA NECESIDAD'),
  P('La forma en que se ha desarrollado la separación absoluta entre las esferas públicas y privada y de éstas en torno al desarrollo de actividades que interesan a la sociedad, se muestra propicia al afianzamiento de una concepción material de los asuntos públicos vinculados a su gestión, si bien siguen conservando su condición de tales, pueden en determinados momentos participar en el desempeño de actividades que en principio poseen características de funciones públicas, predicado que, según lo expuesto, tiene un fundamento material, en cuanto consulta, de preferencia, la función y el interés públicos involucrados en las tareas confiadas a sujetos particulares, por ello, es menester de seguridad y confianza pública el desarrollar todos y cada uno de los actos de la administración conforme está reglamentado, en aras de conservarle la seguridad jurídica que representan.'),
  P('La ',E,', está categorizada como una institución de primer nivel de atención cuyo objetivo es ofrecer servicios de salud entendidos como un servicio público a cargo del Municipio y como integrante del Sistema General de Seguridad Social en Salud (SGSSS).'),
  P('Que los artículos 1 y 4 del Decreto 1876 de 1994 señalan que las Empresas Sociales del Estado, constituyen una categoría especial de entidad pública, descentralizada, con personería jurídica, patrimonio propio y autonomía administrativa, creadas y reorganizadas por ley o por las asambleas o concejo y entre cuyos objetivos se establece entre otros, satisfacer los requerimientos del entorno, adecuando continuamente sus servicios y funcionamiento y garantizar los mecanismos de la participación ciudadana y comunitaria establecidos por la ley y los reglamentos.'),
  P('Entendido lo anterior, se debe exponer entonces que por la imposibilidad material de cubrir con el talento humano propio todas las actividades que requiere el objeto a satisfacer, por mantener el desarrollo de las actividades operativas y asistenciales que hacen parte del funcionamiento natural de la entidad.'),
  P('Como es sabido, las empresas sociales del estado requieren para su mantenimiento la solvencia de las obligaciones que en el curso natural de sus funciones pueden adquirir, es así que necesita realizar de manera constante, cobro y gestiones de los servicios asistenciales prestados, encontrando un equilibrio para adquirir y pagar obligaciones manteniendo la eficiente operatividad del centro hospitalario.'),
  SEC('3. CONVENIENCIA Y OPORTUNIDAD'),
  ...c.p.conveniencia.map(t=>P(x(t,'conveniencia'))),
  P('La satisfacción de la necesidad expuesta, resulta conveniente teniendo clara la necesidad del servicio; en el entendido que es conveniente la satisfacción de esta necesidad coadyuvara al cumplimiento y obligaciones naturales de la entidad, por lo anterior es oportuno impartir el respectivo proceso de contratación.'),
  P('Es así que a sabiendas que la presente contratación tiene como finalidad coadyuvar a mantener el cumplimiento de los fines misionales de la entidad establecidos en el Decreto 1876 de 1994 en el artículo 2 El objetivo de las Empresas Sociales del Estado será la prestación de servicio de salud, entendidos como un servicio público a cargo del Estado y como parte integrante del Sistema de Seguridad Social en Salud.'),
  P('En este orden de ideas, es oportuno impartir el proceso de contratación, en aras del cumplimiento de la ',obj,' Fundamentándose en las siguientes consideraciones:'),
  UL([['Realizar la ',obj],
   ['La ',E,' no posee el personal suficiente para el desarrollo de las actividades que se requieren cumplir en satisfacción del objeto contractual que se pretende satisfacer.'],
   ...c.p.consideraciones.map(t=>[x(t,'consideraciones')]),
   ['La contratación repercutirá de manera directa en las buenas y asertivas decisiones administrativas.'],
   ['Adoptar procedimientos para que se realice la supervisión de estas actividades bajo su control.'],
   ['Es necesario entonces, iniciar proceso de contratación con el propósito de lograr suplir la necesidad, mejorar y asegurar la prestación de los servicios de salud.'],
   ['El cubrimiento de esta necesidad redundara en la buena marcha y eficiencia de la labor administrativa y operativa.']]),
  P('Para tal fin la ',E,', cuenta con:'),
  UL([['El personal idóneo y disponible para efectuar los procedimientos administrativos de contratación, y a su vez los recursos económicos dispuestos en el Presupuesto General de Rentas y Gastos vigencia ',anio,' por concepto de venta de servicios.']]),
  P('La EMPRESA SOCIAL DEL ESTADO en sus actuaciones contractuales buscará la satisfacción de las necesidades y el logro de sus fines, a través de la correcta asignación y utilización de sus recursos de tal forma que garantice un razonable costo económico con mayores beneficios para el Hospital Local ',M,'.'),
  SEC('4. CONDICIONES TÉCNICAS PARTICULARES'),
  P(b('4.1. PROCESO: '),'CONTRATACIÓN DIRECTA'),
  P(b('4.2. OBJETO: '),obj),
  P(b('4.3. OBLIGACIONES GENERALES.')),
  P(b('CONTRATANTE: '),...D.general.contratante.map((t,i)=>(i<D.general.contratante.length-1?(i+1)+') ':'')+t+' ')),
  P(b('CONTRATISTA: '),...ob.flatMap((t,i)=>[(i+1)+') ',...t,' '])),
  P(b('4.4. SUPERVISORA: '),x(c.sup.c,'supervisor'),' O QUIEN HAGA SUS VECES'),
  P(b('4.5. VIGENCIA: '),x(c.plazoL,'plazo')),
  P(b('4.6. VALOR: '),x(c.valL,'valor')),
  P(b('4.7. FORMA DE PAGO: '),'Se pagará en ',...pago,', después de radicación de informe de gestión, cuenta de cobro y anexando la seguridad social correspondiente, previo certificado por el supervisor del contrato designado para el caso, y estas serán canceladas dentro de los diez (10) días calendario siguientes a su radicación en la tesorería de la entidad contratante.'),
  P(b('4.8. LUGAR DE EJECUCIÓN: '),'Municipio de ',M,', y dentro del territorio departamental o nacional.'),
  P(b('4.9. SOPORTE TÉCNICO:')),
  UL([['Certificación expedida por la ',AJ.supAdmCargo.toLowerCase(),' donde se suscribe la necesidad.'],['Solicitud de CDP.'],[...cdp,' VALOR: ',x(c.valL,'valor')]]),
  P(b('4.10. CLASIFICADOR DE BIENES Y SERVICIOS.')),
  TBL([[b('CÓDIGO UNSPSC'),b('DESCRIPCIÓN')],['80111600','SERVICIOS DE PERSONAL TEMPORAL'],['85101600','PERSONAS DE SOPORTE DE PRESTACIÓN DE SERVICIOS DE SALUD']],[30,70],{head:1}),
  SEC('5. MODALIDAD DE SELECCIÓN DEL CONTRATISTA Y SU JUSTIFICACIÓN, INCLUYENDO LOS FUNDAMENTOS JURÍDICOS.'),
  P('En este ítem desarrollaremos la modalidad de contratación simplificada y su respectiva Justificación la cual incluirá con esta los fundamentos legales. Es de aclarar que la siguiente contratación se realiza invocando la Causal encontrada en la Ley 1150 de 2007 Título II Artículo 14 y sustentada en el ',AJ.manual,' del ',AJ.manualFecha,' Cap. II Artículo 15, modalidad de contratación directa, configurándose en razón de la menor cuantía determinada dentro de la ley y la entidad.'),
  SEC('6. VALOR ESTIMADO DEL CONTRATO, ANÁLISIS Y JUSTIFICACIÓN DEL MISMO'),
  P('En igual medida se debe tener claro que el objeto del contrato a celebrar y la cuantía del mismo asciende a la suma ',x(c.valL,'valor'),', se estima que el mecanismo para seleccionar al contratista es por intermedio de la modalidad de contratación directa un contrato de prestación de servicios definido en el Decreto 1082 del 26 de mayo de 2015 y Ley 80 de 1993, que permite la ejecución de actividades con personas naturales o jurídicas que tengan idoneidad y experiencia en el área a contratar de lo cual se deberá dejar constancia. De igual manera se deja claro que el valor descrito anteriormente será pagado ',String(S.pagot||'').trim()?'según la forma de pago establecida':'mediante cuotas partes iguales',' durante la ejecución del contrato, previa certificación de cumplimiento de las obligaciones.'),
  P('Teniendo de presente lo anterior, se deja constancia que el valor de la contratación surge y se fijó atendiendo las máximas de experiencia en las contrataciones realizadas por esta entidad, por los contratos de referencia encontrados en Secop I y los precios brindados y fijados por Colombia Compra Eficiente con objetos y obligaciones similares y/o iguales.'),
  SEC('7. ALCANCES DEL CONTRATO'),
  P('El objeto del contrato tiene los siguientes alcances:'),
  UL([...c.p.alcances.map(t=>[x(t,'alcances')]),['Repercute indirectamente en la eficiente garantía de los derechos de toda la comunidad del territorio del Municipio de ',M,' (',Dp,').']]),
  P('Se evidencia dentro de lo expuesto la existencia de la necesidad planteada, por lo que resulta imprescindible adelantar el correspondiente proceso de contratación, para la buena marcha y efectivo cumplimiento de los cometidos de la ',E,'.'),
  SEC('8. CRITERIOS PARA SELECCIONAR LA OFERTA MÁS FAVORABLE.'),
  P('Teniendo de presente que se requiere satisfacer la necesidad presentada con ',obj,' Surge la necesidad de establecer los criterios para seleccionar la oferta más favorable:'),
  TBL([[b('CRITERIOS'),b('DESCRIPCIÓN')],
   [b('CAPACIDAD LEGAL'),'Como primer criterio se verificará la capacidad de contratar, se verificará si el proponente se encuentra habilitado legalmente para ejercer un contrato de prestación de servicios con la entidad, atendiendo a las normas legales vigentes. Para el presente asunto que se pretende contratar la persona debe tener los permisos y licencias que lo habilitan para el ejercicio de la actividad que se pretende suscribir.'],
   [b('CAPACIDAD ECONÓMICA'),'Como segundo criterio la capacidad económica, el contratista debe demostrar que puede tener la capacidad económica para el desarrollo integral del objeto contractual por sus propios medios.'],
   [b('IDONEIDAD'),'Como tercer criterio se verificará la idoneidad, en la cual se verificará si cumple con los conocimientos requeridos para el ejercicio del objeto contractual, la cual debe ser acreditada mediante titulación o experiencias en temas relacionados.'],
   [b('DISPONIBILIDAD'),'Como cuarto criterio se verificará la disponibilidad, de manera preferible la persona se deberá encontrar disponible de tiempo y para la ejecución de las labores, actividades y obligaciones que se acepten ejecutar.'],
   [b('EXPERIENCIA'),'Como quinto criterio se verificará la experiencia, tal se verificará con los certificados que la persona aporte, en la cual se debe constatar el ejercicio de igual o similar al objeto de la actividad a contratar, con la aclaración que es únicamente necesaria conocimiento o experiencia en temas relacionados desarrollados de manera profesional directa o indirectamente con el objeto a contratar, suscritos con entidades públicas o privadas.'],
   [b('PRECIO'),'Se escogerá el menor precio establecido en la presentación de propuestas, si está garantiza el cumplimiento total de las obligaciones y parámetros.']],[26,74],{head:1}),
  P(b('8.1. CUALIDADES DEL CONTRATISTA:')),
  UL([['El contratista debe ser legalmente capaz para la suscripción y ejercicio del contrato para lo cual debe, no solamente contar con sus documentos anexos que comprueben su capacidad legal sino también, los permisos necesarios para el ejercicio del objeto contractual.'],
   ['El contratista deberá contar con la suficiente capacidad económica para ejecutar el objeto contractual de manera integral.'],
   ['Debe ser idóneo demostrando, no solamente la capacidad legal y económica para ejercer el objeto del contrato, sino también los conocimientos precisos y certeros dentro del área a contratar.'],
   ['Debe contar con disponibilidad, en este sentido el contratista debe contar con el personal suficiente con disponibilidad de tiempo para la planificación y realización de las actividades y demás acciones tendientes a prestar las ayudas necesarias de manera remota en las eventualidades que puedan surgir inconvenientes o percances que imposibiliten la ejecución del contrato.']]),
  P(b('8.2. REQUISITOS MÍNIMOS:')),
  UL(['Carta de presentación de la oferta o propuesta de prestación de servicios.','Hoja de vida formato único del contratista para persona natural, de ser persona jurídica deberá aportar hoja de vida en formato único del representante legal y de la persona jurídica.','Fotocopia de la cédula de ciudadanía para personas naturales.','Certificado antecedentes disciplinarios - Procuraduría.','Certificado de antecedentes fiscales - Contraloría.','Certificado de antecedentes judiciales - Policía Nacional.','Certificado de medidas correctivas - Policía Nacional.','Certificado de consulta de inhabilidades por delitos sexuales cometidos contra menores de 18 años - Ley 1918 de 2018.','Certificado de registro de deudores morosos – REDAM.','Registro Único Tributario - RUT.','Declaración juramentada de bienes y rentas.','Acreditar estar vinculado a un régimen de salud y otro o al mismo para pensiones.','Acreditar idoneidad mediante título o acta de grado.','Acreditar experiencia.'].map(t=>[t])),
  P(b('8.3. CAUSALES DE RECHAZO:')),
  ...['Cuando el proponente está incurso en causal de inhabilidad y/o incompatibilidad.','Cuando el proponente se encuentre registrado en el boletín expedido por la Contraloría General de la República como responsable fiscal, situación que la entidad verificará.','Cuando el objeto social del proponente que sea persona jurídica, no guarde relación con el objeto a contratar.','Cuando el representante legal de la persona jurídica tenga limitaciones para contratar y no tenga la autorización expresa del órgano social competente para presentar oferta y/o celebrar el Contrato.','Cuando se compruebe que la información contenida en los documentos que componen la oferta no es veraz o no corresponde con la realidad.','Cuando la oferta supere el presupuesto disponible para contratar.','Cuando el proponente con el precio más bajo no subsane los requisitos habilitantes en el tiempo requerido por la entidad y así sucesivamente.','Cuando los precios estén por encima ítem por ítem del promedio estipulado en el estudio de mercado.','Cuando ninguna de las ofertas se ajuste a las exigencias contenidas en la presente invitación pública.'].map((t,i)=>P('8.3.'+(i+1)+'. '+t)),
  P(b('8.4. ACÁPITE:')),
  UL([['Si se presentan oferentes pertenecientes al régimen simplificado en el análisis económico del precio más bajo se tendrá en cuenta el valor total de la oferta antes del impuesto del IVA.'],['En caso de presentarse controversia entre las características técnicas de la invitación pública, con las fichas técnicas, será el evaluador del proceso, el encargado de definir la decisión final.'],['Si se presentan proponentes con propuestas económicas inferiores al presupuesto estimado, la entidad se reserva el derecho de incrementar las cantidades, teniendo en cuenta la disponibilidad presupuestal.']]),
  SEC('9. SOPORTE QUE PERMITA LA TIPIFICACIÓN, ESTIMACIÓN, Y ASIGNACIÓN DE LOS RIESGOS PREVISIBLES QUE PUEDAN AFECTAR EL EQUILIBRIO ECONÓMICO DEL CONTRATO.'),
  P('De conformidad con el Estatuto y Manual de Contratación de la ',E,', se realiza el presente análisis del riesgo para la contratación ',obj,' Con el presente estudio se pretende contribuir a la buena prestación de servicios del personal de la ',E,' y lograr, que las partes del contrato estatal puedan hacer las previsiones necesarias para mitigar los riesgos, por ello se hacen necesario presentar un estudio para estimar, tipificar y cuantificar los riesgos previsibles involucrados en la contratación. Para los efectos de los diferentes servicios de selección, se entenderán las siguientes categorías de riesgo:'),
  P(b('Riesgo Previsible: '),'Son los posibles hechos o circunstancias que por la naturaleza del contrato y de la actividad a ejecutar es factible su ocurrencia.'),
  P(b('Riesgo imprevisible: '),'Son aquellos hechos o circunstancias donde no es factible su previsión, es decir el acontecimiento de su ocurrencia, tales como desastres naturales, actos terroristas, guerra o eventos que alteren el orden público.'),
  P(b('Tipificación del Riesgo: '),'Es la enunciación que se hace de aquellos hechos previsibles constitutivos de riesgo que, en criterio de la interventoría, pueden presentarse durante y con ocasión de la ejecución del contrato.'),
  P(b('Asignación del Riesgo: '),'Es el señalamiento que hace la interventoría, de la parte contractual que deberá soportar total o parcialmente la ocurrencia de la circunstancia tipificada, asumiendo su costo.'),
  P(b('Riesgos Previsibles: '),'Para los efectos del presente servicio de selección, son riesgos previsibles:'),
  P('A. Falta de idoneidad en el desarrollo del servicio.'),P('B. Accidentes de trabajo o del ejecutante del servicio.'),P('C. Daños a bienes ajenos y a terceros.'),P('D. Incumplimiento de las obligaciones derivadas de pagos de la Seguridad Social.'),
  P(b('Riesgos Imprevisibles: '),'Se consideran riesgos no previsibles, por la incertidumbre de su ocurrencia, los de fuerza mayor, caso fortuito o hechos de terceros, tales como desastres naturales, actos terroristas, guerras, asonadas o eventos que alteren el orden público.'),
  TBL([[b('RIESGO'),b('TIPIFICACIÓN'),b('ASIGNACIÓN CONTRATISTA')],
   ['Falta de idoneidad en el desarrollo del servicio','No se ejecutan los lineamientos de los presentes estudios previos poniendo en riesgo de declaratoria de caducidad o incumplimiento al contratista por parte de la E.S.E.','X'],
   ['Buen manejo e inversión del anticipo','Sucede cuando se le da un mal manejo al adelanto y no se cumple las obligaciones contractuales.','X'],
   ['Accidente de trabajo o ejecutante del servicio','Ocurre cuando en el desarrollo del servicio el ejecutante, sufre algún tipo de lesión o daño a su integridad física, mental o moral.','X'],
   ['Daños a bienes ajenos y a terceros','Ocurre en los eventos de que trata el Capítulo I del título VII de la Ley 599 de 2000 (Código Penal).','X'],
   ['Incumplimiento de las obligaciones derivadas de pagos de la seguridad social','Ocurre cuando se puede percatar de la falta de pago de los aportes a la seguridad social.','X'],
   ['Filtración de información por falta de Seguridad','Ocurre cuando por fallas en el sistema o por motivos reprochables y controlables al contratista se filtra información legalmente no autorizada.','X']],[32,53,15],{head:1,center:[2]}),
  P('De acuerdo con la distribución que se hizo, no procederán reclamaciones del Contratista, basadas en la ocurrencia de alguno de los riesgos asumidos por él, y, en consecuencia, la respectiva entidad no hará ningún reconocimiento, ni ofrecerá garantía alguna, que permita eliminar o mitigar los efectos causados por la ocurrencia de alguno de estos riesgos, salvo que dicho reconocimiento o garantía se encuentren expresamente pactados en el contrato.'),
  P(b('ANÁLISIS CUALITATIVO DE RIESGOS CON SU PROBABILIDAD E IMPACTO.')),
  TBL([[b('Riesgo'),b('Probabilidad'),b('Impacto'),b('Asignación')],['Riesgos sociales o políticos','Baja','Media – Baja','E.S.E.'],['Riesgos operacionales','Media – Baja','Media – Baja','El contratista'],['Riesgos financieros','Media – Baja','Media – Baja','El contratista'],['Riesgos regulatorios','Media – Baja','Media – Baja','El contratista'],['Riesgo tecnológico','Media – Baja','Media – Alta','El contratista']],[34,22,22,22],{head:1}),
  TBL([[b('TIPIFICACIÓN'),b('ESTIMACIÓN'),b('ASIGNACIÓN')],
   [{span:1,c:[b('RIESGO EN PLANIFICACIÓN Y EJECUCIÓN DEL SERVICIO')]}],
   ['Información errónea o desactualizada suministrada por la entidad','10%','Entidad contratante'],
   ['Uso o recolección de información errada','15%','Contratista, salvo que la información errada provenga de la misma entidad'],
   ['Estimación inadecuada de los costos','5%','Contratista'],
   ['Negligencia, imprudencia o temeridad en los mandatos','20%','Contratista'],
   ['Uso indebido de información','10%','Contratista'],
   ['Accidentes de trabajo y enfermedades profesionales','5%','Contratista, quien debe cubrir el riesgo conforme a las normas que regulan el sistema ARL'],
   ['Falta de calidad en el servicio prestado','10%','El Supervisor del contrato debe vigilar su ejecución, so pena de no certificarla'],
   [{span:1,c:[b('EVENTOS DERIVADOS DE CIRCUNSTANCIAS ECONÓMICAS O LEGALES')]}],
   ['Financiamiento del contrato','100%','Contratista'],
   ['Incremento en impuestos que afectan a todos los contribuyentes y a todas las actividades','5%','Contratista'],
   ['Incremento en impuestos que afectan la actividad del contratante, siendo tal actividad objeto del contrato','5%','Contratista, a quien la entidad podrá llevar a un punto de no pérdida, siempre y cuando acredite que el incremento es de tal magnitud que le ha conducido a pérdida.']],[45,15,40],{head:1,center:[1]}),
  SEC('10. GARANTÍAS EXIGIDAS EN EL PROCESO DE CONTRATACIÓN.'),
  P('La administración de la ',E,', considera que dada la cuantía y el objeto del contrato a celebrar no se requerirá de la exigencia de garantías atendiendo lo normado el inciso 5 del Artículo 7 de la Ley 1150 del 16 de julio de 2007 en armonía con el 2.2.1.2.1.4.5 del Decreto 1082 de 2015, y lo planteado en el estudio de oportunidad y conveniencia.'),
  P('Sumado a lo anterior, no se exigirá la constitución de garantías por ser las obligaciones y forma de pago de tracto sucesivo y para obtener el pago de las actividades o gestión realizada, previamente se requiere certificación del cabal cumplimiento de las obligaciones debidamente supervisadas.'),
  SEC('11. EXCEPCIÓN DEL PAGO DE PRESTACIONES.'),
  P('De acuerdo con lo establecido en la Ley 80 de 1993 el CONTRATISTA no tendrá otra contraprestación distinta a la señalada en la cláusula del valor del contrato.'),
  SEC('12. CLÁUSULAS EXCEPCIONALES ESTABLECIDAS EN EL ARTÍCULO 42 DEL ACUERDO No. 002 DE 2014, LEY 80 DE 1993 Y ARTÍCULO 17 DE LA LEY 1150 DE 2007.'),
  P(b('CLÁUSULA PENAL PECUNIARIA: '),'En caso de incumplimiento total, culpable y definitivo por parte del Contratista, este pagará a la ',E,' a título de pena, una suma equivalente al diez por ciento (10%) del valor del Contrato, que se imputará al de indemnización de los perjuicios que reciba la ',E,' por el incumplimiento.'),
  P(b('MULTA: '),'En caso de mora o incumplimiento parcial de las obligaciones que en desarrollo de este Contrato contrae EL CONTRATISTA, la ',E,' podrá imponerle mediante resolución motivada en calidad de multa, sanciones pecuniarias equivalentes al uno por ciento (1%) del valor del contrato, las cuales sumada entre sí, no podrán exceder el diez por ciento (10%) de dicho valor, salvo casos de fuerza mayor o casos fortuitos.'),
  SEC('13. VALIDEZ Y TÉRMINO PARA ACEPTACIÓN O RECHAZO DE LA PROPUESTA.'),
  P('Después de recibidas las propuestas, la entidad tiene el término de hasta dos (02) días para la elección y suscripción, para todos los efectos, se entenderá que la oferta se mantendrá vigente por treinta (30) días y hasta la liquidación del contrato.'),
  SEC('14. LUGAR DE ENTREGA DE PROPUESTAS.'),
  P('Las propuestas se presentarán de manera física en ',M,', ',AJ.direccion,'.'),
  SEC('15. LEGALIZACIÓN DEL CONTRATO.'),
  P('Que después de contener el requerimiento de necesidad, la solicitud de CDP, el certificado de disponibilidad presupuestal, estudios previos, propuesta de servicios con hoja de vida y anexos, suscripción del contrato, anexar certificado de registro presupuestal, constitución y aprobación de la póliza, y suscripción del acta inicio.'),
  SEC('16. LIQUIDACIÓN DEL CONTRATO.'),
  P('Se liquidará dentro de los cuatro (04) meses siguientes a su terminación, mediante acta firmada de común acuerdo por las partes, la cual contendrá un balance sobre la ejecución del mismo y los desembolsos realizados al CONTRATISTA y los demás acuerdos a que se llegare sobre su ejecución. Dentro de este plazo, las partes acordarán los ajustes, revisiones y reconocimientos a que haya lugar, de los cuales quedará constancia en el acta de liquidación.'),
  P('Si el contratista no se presenta a la liquidación del contrato o las partes no llegan a un acuerdo sobre el contenido de la misma, será practicada directa y unilateralmente por la ',E,' adoptándose en acto administrativo motivado.'),
  SEC('17. CONDICIONES GENERALES ÁREA PRESUPUESTAL, FINANCIERA Y JURÍDICA'),
  P(b('ESTUDIO TÉCNICO Y ECONÓMICO')),
  P('Se ha realizado un presupuesto oficial para realizar este servicio ',obj,' Con base en el mismo se pueden solicitar recursos del presupuesto de la ',E,', en este sentido y por tratarse de una contratación inferior a los veintiocho (28) S.M.M.L.V., por el valor de la suma de ',x(c.valL,'valor'),', se escogerá y estudiarán dos propuestas enviadas por carta de invitación para que presentasen cotización propuesta, escogiendo la que mayor acredite experiencia, teniendo entonces la garantía y confiabilidad de que la ejecución contractual se cumplirá según los lineamientos establecidos. Por lo que se anexan los siguientes documentos técnicos:'),
  UL([['Requerimiento de Necesidad.'],['Solicitud de CDP.'],[...cdp,' VALOR: ',x(c.valL,'valor')]]),
  P(b('ESTUDIO JURÍDICO')),
  P('La garantía de la transparencia en la inversión de los recursos públicos dentro del marco contractual debe estar garantizado por los principios de transparencia, economía, coordinación, eficiencia, celeridad, planeación, responsabilidad, buena fe, imparcialidad y debido proceso. Por lo que respecto a las facultades de la Ley 80 de 1993, Ley 1150 del 2007, Ley 1438 del 2011, Decreto 855 de 1994; y en concordancia con la Ley 100 de 1993, Ley 1474 del 2011 y Decreto 1082 del 2015 y Manual interno de contratación ',AJ.manual,', regulan el marco de la contratación.'),
  UL([['El presente proceso de contratación administrativa está orientado por el manual de contratación de la ESE, en la modalidad de contratación directa.'],['Es deber de la entidad, cumplir con los requisitos de orden jurídico, técnico, administrativo y presupuestal que ordena el estatuto de contratación administrativa y demás normatividad legal para contratar el servicio objeto de este estudio.'],['La entidad debe expedir el certificado de disponibilidad presupuestal con cargo al presupuesto de rentas y gastos de la vigencia ',anio,', con el fin de iniciar al proceso de contratación.'],['La gerente está autorizada para contratar según acuerdo de la Junta Directiva.']]),
  P('Para concluir se evidencia dentro de lo expuesto la existencia de la necesidad planteada, por lo que resulta imprescindible adelantar el correspondiente proceso de contratación, para la buena marcha y efectivo cumplimiento de los cometidos de la ',E,'. Dado en el Municipio de ',M,' ',Dp,', el día ',x(c.fsusL,'fecha de suscripción'),'.'),
  FIR([[xb(AJ.gerente,'gerente')],['GERENTE']])];

 case 'ido':return[
  TIT('CERTIFICADO DE IDONEIDAD'),
  PC(b('LA SUSCRITA '+AJ.supAdmCargo+' DE LA '+E+' – '+Dp.toUpperCase())),
  PC(b('HACE CONSTAR:')),
  P('Que ',...persona,', ha demostrado idoneidad con lo anotado en su propuesta y hoja de vida',c.p.idoneidad?[' ',x(c.p.idoneidad,'idoneidad')]:'',', para ejecutar el objeto, ',obj,' circunstancia que le permite contratar.'),
  P('Para constancia se expide y se firma en el municipio de ',M,' (',Dp,') el día ',x(c.fsusL,'fecha de suscripción'),'.'),
  FIR([[xb(AJ.supAdm,'subgerente administrativa')],[AJ.supAdmCargo]])];

 case 'des':return[
  PI(M,' – ',Dp,', ',x(c.fsusL,'fecha de suscripción')),
  TBL([[b('PARA'),[xb(c.sup.n,'supervisor'),' - ',c.sup.c]],[b('DE'),[xb(AJ.gerente,'gerente'),' – GERENTE']],[b('ASUNTO'),b('DESIGNACIÓN DE SUPERVISIÓN')]],[22,78]),
  P('Por medio del presente me permito comunicarle que ha sido designado (a) para ejercer la supervisión y control de la debida ejecución del objeto y las obligaciones contractuales que se relacionan a continuación:'),
  TBL([[b('CONTRATO'),b('CONTRATISTA'),b('OBJETO')],[[xb(c.num,'No. contrato')],[xb(S.nombre,'nombre'),', ',c.tr.id,' con ',x(c.doc,'documento')],[obj]]],[20,28,52],{head:1}),
  P('Con el fin de adelantar un adecuado seguimiento a la ejecución contractual, es su obligación realizar un estudio completo y detallado del contrato y de los documentos que soportan la contratación, además de adelantar entre otras, las siguientes actividades:'),
  UL([['Los supervisores deben verificar el cumplimiento del objeto contractual y de las obligaciones contraídas por las partes.'],['Están facultados para solicitar a los contratistas informes, aclaraciones y explicaciones sobre el desarrollo de la ejecución contractual.'],['Y serán responsables por mantener informada a la entidad contratante de los hechos o circunstancias que puedan afectar la ejecución del contrato, o que puedan poner o pongan en riesgo el cumplimiento del contrato, o cuando tal incumplimiento se presente elaborando el informe respectivo.']]),
  P('Por lo tanto, corresponde al supervisor llevar a cabo:'),
  UL(['La vigilancia permanente y la correcta ejecución del contrato.','Exigir, prevenir, solicitar y verificar el control y seguimiento del contrato, en los términos previstos en la ley.','Presentar informes y/o certificación en los que conste el cumplimiento del objeto, la suscripción de actas de inicio, suspensión, entrega de los elementos y prestación oportuna del servicio contratado.','Terminación y liquidación del contrato, cuando a ello hubiere lugar, la relación de pagos y saldos pertinentes.','Informar al gerente cualquier acontecimiento que impida el normal desarrollo del contrato.','Estudiar las solicitudes, sugerencias, reclamaciones y consultas del contratista.','Exigir la documentación e información que estime pertinente y necesaria para el cabal cumplimiento de sus obligaciones como supervisor.','Exigir la acreditación del cumplimiento de las obligaciones adquiridas con el sistema de seguridad social integral y parafiscal según sea el caso.','Aprobar las solicitudes de pago, y todas las demás obligaciones que deban cumplir las partes y/o el contratista, señaladas en el respectivo contrato.'].map(t=>[t])),
  P('Así mismo el Supervisor (a) designado (a) deberá, exigir, al contratista mantener las garantías requeridas vigentes, por el término de ejecución del contrato, hasta su liquidación o por el término que determine la ley según los amparos solicitados.'),
  P('Por otra parte, en ejercicio de la actividad de supervisión, deberán autorizarse los pagos respectivos previa verificación de su procedencia, para lo cual el contratista deberá presentar los informes de ejecución en los cuales se describa detalladamente cada una de las actividades realizadas durante el periodo, las cuentas de cobro o facturación, teniendo en cuenta las particularidades de cada contrato, así como verificar el cumplimiento por parte del contratista de sus obligaciones con el Sistema de Seguridad Social Integral y pago de aportes parafiscales cuando haya lugar a ello.'),
  P('Aunado a lo anterior el supervisor deberá revisar y analizar los informes antes de certificar el cumplimiento y avalar el pago, los cuales deben reflejar la certeza de las condiciones de ejecución del contrato, anexando los productos o documentos que soporten la actividad y sean pertinentes para el efecto.'),
  P('En lo relacionado con la conformación del expediente contractual en la etapa de ejecución, los supervisores deben remitir mensualmente al área de contratación de la E.S.E. HOSPITAL LOCAL ',M.toUpperCase(),', todos los soportes de ejecución, informes de actividades, copia del recibo a satisfacción, productos si hay lugar a ello y demás documentos que soporten la ejecución del contrato.'),
  P('En los casos de contratos de prestación de servicios y de apoyo a la gestión que contemplen y generen gastos de desplazamiento por comisiones, el supervisor del contrato deberá verificar el cumplimiento del objeto de la comisión y de la entrega del informe con los respectivos soportes teniendo en cuenta lo establecido en el procedimiento de legalización de viáticos y la normatividad aplicable.'),
  P('Una vez finalice el contrato cuya supervisión le corresponda, tendrá la obligación de expedir un informe final de supervisión, la certificación final de cumplimiento del objeto contractual y proyectar el acta de liquidación respectiva, en los casos que aplique, la cual deberá venir acompañada de la certificación de pagos y el certificado de saldos y pagos expedidos por la tesorería de la E.S.E. HOSPITAL LOCAL ',M.toUpperCase(),'.'),
  P('Sea esta la oportunidad para reiterarle que en la oficina de contratación se le brindará el apoyo y asesoría que requiera.'),
  P('Atentamente,'),
  FIR([[xb(AJ.gerente,'gerente')],['GERENTE']])];

 case 'not':return[
  TIT('NOTIFICACIÓN A SUPERVISOR'),
  TBL([[b('CONTRATO No.'),[xb(c.num,'No. contrato')]],[b('NOMBRE DEL SUPERVISOR'),[xb(c.sup.n,'supervisor')]],[b('CARGO'),[c.sup.c]],[b('FIRMA DEL SUPERVISOR'),{alto:1,c:['']}],[b('FECHA DE NOTIFICACIÓN'),[x(c.fsusL,'fecha de suscripción')]]],[35,65]),
  FIR([[xb(AJ.gerente,'gerente')],['GERENTE']])];

 case 'con':return[
  TIT('CONTRATO No. ',xb(c.num,'No. contrato')),
  TBL([[b('CONTRATANTE'),E],[b('NIT DEL CONTRATANTE'),AJ.nit],[b('CONTRATISTA'),[xb(S.nombre,'nombre')]],[b('NIT/C.C. DEL CONTRATISTA'),[x(cc(S.ndoc),'documento')]],[b('OBJETO'),[obj]],[b('PLAZO DE EJECUCIÓN'),[x(c.plazoL,'plazo')]],[b('VALOR'),[x(c.valL,'valor')]]],[30,70]),
  P('Entre los suscritos a saber: ',xb(AJ.gerente,'gerente'),', mayor de edad, vecina del municipio de ',M,' (',Dp,'), con cédula de ciudadanía No. ',AJ.gerCc,', expedida en ',AJ.gerExp,', actuando en nombre y representación de la ',E,', con NIT. N° ',AJ.nit,', nombrada mediante ',AJ.gerDecreto,' y ',AJ.gerActa,' en su calidad de Gerente y por ende representante legal, quien para efectos del presente contrato en adelante se denominará EL CONTRATANTE o la ENTIDAD; por una parte y por la otra ',...persona,', que en adelante se denominará ',c.tr.al,', quien declara bajo la gravedad del juramento no encontrarse ',c.tr.inc,', en causal alguna de inhabilidad e incompatibilidad para contratar, de acuerdo con lo previsto artículo 8° de la Ley 80 de 1993, las contempladas en la ley 1474 de 2011, y en el ART. 7 del Manual de Contratación de la ',E,', y demás normas aplicables a la materia; quien para efectos del presente contrato se ha convenido celebrar el presente contrato de PRESTACIÓN DE SERVICIOS, previa las siguientes ',b('CONSIDERACIONES:')),
  P(b('PRIMERO: '),'Que EL CONTRATANTE está facultado legal y estatutariamente para celebrar los contratos que sean necesarios para la prestación de los servicios que ofrece la ESE HOSPITAL LOCAL ',M.toUpperCase(),', para hacer posible el cumplimiento de su objeto social en especial la obligación contractual que se pretende desarrollar.'),
  P(b('SEGUNDO: '),'Valorando la planta general de cargos y las condiciones administrativas actuales de la ',E,', esta no dispone de las condiciones logísticas para realizar el desarrollo de estas acciones, conforme con la certificación expedida por la ',AJ.supAdmCargo.toLowerCase(),', de la E.S.E. En consecuencia, la ',E,' requiere de una persona natural o jurídica con experiencia en el objeto relacionado, apoyando la gestión institucional de la ',E,', para la adecuada ejecución de actividades de cobro y gestión, para tal fin esta contratación se encuentra regida por el Manual de Contratación, autorizada mediante la modalidad de Contratación Directa. En atención al objeto y cuantía contractual, este contrato se enmarca dentro del procedimiento establecido en el Manual de Contratación de la entidad, teniendo en cuenta los factores de selección que permiten identificar la oferta más favorable.'),
  P(b('TERCERO: '),'La Subdirección Financiera - Oficina de Presupuesto de la Empresa Social del Estado Hospital Local ',M,', constató que existe disponibilidad en el presupuesto de vigencia fiscal ',anio,' en el rubro denominado ',x(c.p.rubroNombre,'nombre del rubro'),' para cubrir los gastos que ocasione este contrato y, por lo tanto, expidió el CERTIFICADO DE DISPONIBILIDAD PRESUPUESTAL; En consecuencia, la ',E,' y EL CONTRATISTA suscriben el presente contrato de PRESTACIÓN DE SERVICIOS, el cual se regirá en forma general por el Manual de Contratación de la E.S.E., las reglas del derecho privado, y discrecionalmente por las cláusulas exorbitantes previstas en el estatuto general de contratación de la administración pública y en forma específica por el siguiente clausulado:'),
  P(b('CLÁUSULA PRIMERA: OBJETO DEL CONTRATO. '),'El presente contrato tiene como Objeto ',obj),
  P(b('CLÁUSULA SEGUNDA: ALCANCE. '),'El alcance del objeto del contrato obliga al contratista a desarrollar todas las obligaciones y actividades detalladas para la óptima y eficaz operación de la entidad contratante, teniendo el siguiente alcance: ',...[...c.p.alcances.map(t=>[x(t,'alcances')]),['Repercute indirectamente en la eficiente garantía de los derechos de toda la comunidad del territorio del Municipio de '+M+' ('+Dp+').']].flatMap((t,i)=>[(i+1)+') ',...t,' '])),
  P(b('CLÁUSULA TERCERA: LUGAR DE EJECUCIÓN. '),'EL CONTRATISTA se obliga a prestar los servicios contratados en el municipio de ',M,' (',Dp,'), su jurisdicción rural y urbana.'),
  P(b('CLÁUSULA CUARTA: DURACIÓN DEL CONTRATO. '),'El presente contrato tendrá un plazo estimado de duración de ',x(c.plazoL,'plazo'),', el cual empezará a contarse desde la suscripción del acta de inicio que se suscribirá una vez se haya acreditado el cumplimiento de los requisitos para su ejecución.'),
  P(b('CLÁUSULA QUINTA: VALOR DEL CONTRATO Y FORMA DE PAGO. '),'El valor del contrato es por la suma de ',x(c.valL,'valor'),', que la ',E,' pagará en ',...pago,', después de radicación de informe de gestión, cuenta de cobro y anexando la seguridad social correspondiente, previo certificado por el supervisor del contrato designado para el caso, y estas serán canceladas dentro de los diez (10) días calendario siguientes a su radicación en la tesorería de la entidad contratante. ',b('PARÁGRAFO PRIMERO: '),'En caso de terminación anticipada o ejecución parcial del contrato, solo habrá lugar al pago proporcional de los productos o actividades acabados y entregados a satisfacción por el contratista a la ',E,'. ',b('PARÁGRAFO SEGUNDO: '),'Del valor de los honorarios pactados se harán los descuentos de ley e impuestos municipales pertinentes.'),
  P(b('CLÁUSULA SEXTA: OBLIGACIONES DEL CONTRATISTA. '),'El contratista, en desarrollo del objeto del presente contrato, se obliga para lograr que se materialicen los productos finales descritos en el alcance de este, cumplir con la obtención y aprobación de los siguientes productos parciales, por cada componente: ',...ob.flatMap((t,i)=>[(i+1)+') ',...t,' ']),b('PARÁGRAFO I: '),'Que las actividades profesionales, de apoyo y logística anteriormente descritas se realizarán bajo estricta supervisión y aprobación de la ',x(c.sup.c,'supervisor'),'.'),
  P(b('CLÁUSULA SÉPTIMA: DERECHOS Y OBLIGACIONES DEL CONTRATANTE. '),'En virtud del presente contrato, el CONTRATANTE se obliga a: ',...D.general.contratante.map((t,i)=>(i<D.general.contratante.length-1?(i+1)+') ':'')+t+' ')),
  P(b('CLÁUSULA OCTAVA: SUPERVISIÓN. '),'La vigilancia y control de cumplimiento de las obligaciones a cargo del CONTRATISTA serán ejercidas por la ',x(c.sup.c,'supervisor'),' de la ',E,' CONTRATANTE o el empleado público que se designe para tal fin, quienes serán responsables de aprobar los pagos o desembolsos, los informes que presente EL CONTRATISTA, de proyectar el acta de liquidación definitiva del contrato, en caso de ser necesario y en general cumplir con las obligaciones señaladas en la normatividad vigente y en el Manual de Contratación de la Entidad. En los contratos que involucren la entrega de recursos para administración de terceros, se debe identificar una supervisión interdisciplinaria para el adecuado seguimiento presupuestal, técnico y jurídico.'),
  P(b('CLÁUSULA NOVENA: IMPUTACIÓN PRESUPUESTAL. '),'Los pagos de dinero que asume el CONTRATANTE en virtud del presente contrato, se sujetan a las apropiaciones presupuestales respectivas y se pagarán con recursos del presupuesto General del ',...cdp,', expedido por el Encargado de Presupuesto de la Entidad. El valor que el CONTRATANTE se compromete a pagar en dinero por el presente contrato se imputará al presupuesto de vigencia fiscal ',anio,'. De dicho valor se descontará el monto de los impuestos y demás acreencias generadas por la celebración o ejecución del contrato, conforme a lo dispuesto en las normas vigentes.'),
  P(b('CLÁUSULA DÉCIMA: GARANTÍAS. '),'La administración de la ',E,', considera que dada la cuantía y el objeto del contrato a celebrar no se requerirá de la exigencia de garantías atendiendo lo normado el inciso 5 del Artículo 7 de la Ley 1150 del 16 de julio de 2007 en armonía con el 2.2.1.2.1.4.5 del Decreto 1082 de 2015, y lo planteado en el estudio de oportunidad y conveniencia. Sumado a lo anterior, no se exigirá la constitución de garantías por ser las obligaciones y forma de pago de tracto sucesivo y para obtener el pago de las actividades o gestión realizada, previamente se requiere certificación del cabal cumplimiento de las obligaciones debidamente supervisadas.'),
  P(b('CLÁUSULA DÉCIMA PRIMERA: MULTAS. '),'En caso de mora o incumplimiento parcial de las obligaciones que en desarrollo de este contrato contrae EL CONTRATISTA, la ',E,' podrá imponerle mediante resolución motivada en calidad de multa, sanciones pecuniarias equivalentes al uno por ciento (1%) del valor del Contrato, las cuales sumada entre sí, no podrán exceder el diez por ciento (10%) de dicho valor, salvo casos de fuerza mayor o casos fortuitos. ',b('PARÁGRAFO: '),'Contra la resolución que imponga la multa procederá el recurso de reposición ante el mismo funcionario que la expidió.'),
  P(b('CLÁUSULA DÉCIMA SEGUNDA: CLÁUSULA PENAL PECUNIARIA. '),'En caso de incumplimiento total o parcial, pero definitivo de las obligaciones por parte del CONTRATISTA éste pagará a EL CONTRATANTE a título de pena, una suma equivalente al diez por ciento (10%) del valor total del contrato y su valor se imputará al de los perjuicios que reciba este por el incumplimiento. De ser el caso, EL CONTRATISTA autoriza a EL CONTRATANTE para que el valor de la cláusula penal sea descontado de los saldos que éste le adeude. Lo anterior no impide que EL CONTRATANTE pueda perseguir por vía judicial el pago del valor de los perjuicios que no se alcanzaren a cubrir con los saldos que se adeuden a EL CONTRATISTA.'),
  P(b('CLÁUSULA DÉCIMA TERCERA: CLÁUSULAS EXCEPCIONALES. '),'De conformidad con lo establecido en el inciso 2 del artículo 14 de la Ley 80 de 1993, se pactan en este contrato las cláusulas excepcionales, de interpretación, modificación y terminación unilaterales, así como la caducidad por incumplimiento de que tratan los artículos 15, 16, 17 y 18 Ibídem. El contratante podrá declarar la caducidad administrativa del contrato en caso de que sobrevengan hechos constitutivos de incumplimiento de las obligaciones por parte del contratista, que afecten de manera grave y directa la ejecución de contrato y puedan conducir a comprometer los intereses del contratante. El acto administrativo que eventualmente declare la caducidad deberá hacerse debidamente motivado.'),
  P(b('CLÁUSULA DÉCIMA CUARTA: CESIÓN. '),'El CONTRATISTA no podrá ceder este contrato, total o parcialmente sin autorización previa, expresa y escrita de EL CONTRATANTE.'),
  P(b('CLÁUSULA DÉCIMA QUINTA: SUSPENSIÓN. '),'Por circunstancias de fuerza mayor o caso fortuito, por ser conveniente a los intereses de LA ',E,', y EL MUNICIPIO o por mutuo acuerdo con EL CONTRATISTA, se podrá suspender temporalmente la ejecución total o parcial del contrato, sin que cesen los efectos legales del mismo, en este caso, las partes suscribirán un acta de suspensión temporal en la cual se haga constar dicha circunstancia y la fecha estimada de reiniciación del mismo. ',b('PARÁGRAFO: '),'Una vez suscrita el acta de suspensión se deberá remitir copia de la misma a la compañía de seguros que emitió la garantía única de cumplimiento para que tome las medidas del caso. Superadas las causas que dieron origen a la suspensión del contrato, mediante acta suscrita por las partes se reiniciará su ejecución. EL CONTRATISTA deberá modificar la garantía única teniendo en cuenta el tiempo de suspensión del contrato.'),
  P(b('CLÁUSULA DÉCIMA SEXTA: TERMINACIÓN ANTICIPADA DE COMÚN ACUERDO. '),'Las partes podrán dar por terminado de manera anticipada y de común acuerdo al presente contrato, en cualquier momento, con un aviso anterior a la otra parte con mínimo quince (15) días de anticipación.'),
  P(b('CLÁUSULA DÉCIMA SÉPTIMA: EXCLUSIÓN DE LA RELACIÓN LABORAL. '),'EL CONTRATISTA prestará los servicios objeto del presente contrato por cuenta propia y sin exclusividad, por lo tanto, no existirá vinculación alguna de tipo laboral entre EL CONTRATANTE y EL CONTRATISTA ni se generará obligación de reconocimiento de prestaciones sociales ni de otras prestaciones u obligaciones propias de la relación laboral. LAS PARTES asumirán la total y absoluta responsabilidad laboral, de seguridad social y civil contractual y extracontractual de todas las personas que utilice para la ejecución del objeto del presente Contrato, ya sean empleados o subcontratistas, cualquiera fuere su nivel y categoría.'),
  P(b('CLÁUSULA DÉCIMA OCTAVA: PAGOS A SEGURIDAD SOCIAL. '),'EL CONTRATISTA, está obligado a cumplir y mantener al día sus compromisos de pago al Sistema de Seguridad Social Integral so pena de hacerse merecedor a la imposición de multas que permite la Ley y la declaración de caducidad del contrato.'),
  P(b('CLÁUSULA DÉCIMA NOVENA: REQUISITOS DE PERFECCIONAMIENTO Y EJECUCIÓN. '),'El presente contrato se perfecciona con las firmas de las partes y el registro presupuestal expedido por la Oficina de Presupuesto de la ',E,'. Para su ejecución, EL CONTRATISTA debe cumplir los siguientes requisitos previos: a) Acreditar ante la ',E,', estar a paz y salvo con los pagos de afiliación a los Sistemas de Salud y de Pensiones, cuando a ello hubiere lugar. b) Suscribir el acta de iniciación.'),
  P(b('CLÁUSULA VIGÉSIMA: DOMICILIO PARA NOTIFICACIONES. '),'Para todos los efectos legales el domicilio contractual es el municipio de ',M.toUpperCase(),' (',Dp,').'),
  P(b('CLÁUSULA VIGÉSIMA PRIMERA: RESOLUCIÓN DE CONTROVERSIAS Y LEY APLICABLE. '),'Las partes acuerdan que para la solución de las diferencias y discrepancias que surjan de la celebración, ejecución, terminación o liquidación de este Contrato, acudirán a los procedimientos de transacción, amigable composición o conciliación.'),
  P(b('CLÁUSULA VIGÉSIMA SEGUNDA: CONFIDENCIALIDAD. '),'Las partes se obligan y garantizan que guardarán la debida reserva sobre la información que le sea suministrada en desarrollo del presente contrato y que fue entregada del desarrollo de las actividades aquí descritas, la cual para todos los efectos será considerada como "Información Confidencial" y de propiedad de la otra parte. Así mismo, las partes garantizan que dicha información, no se entregará o suministrará total o parcialmente a ningún tercero o persona ajena o extraña a la otra parte, salvo que este expresamente y por escrito lo autorice o se trate de un requerimiento de una autoridad judicial. La Parte Receptora de la información, se obliga a no revelar de manera verbal, escrita o por cualquier medio, la Información Confidencial a ninguna persona natural o jurídica, aparte de los empleados, consultores, asociados y entidades necesarias para la ejecución del presente contrato sin el consentimiento previo y por escrito de la Parte Reveladora. La Parte Receptora se obliga a tomar las precauciones necesarias y apropiadas para mantener como confidencial la "Información Confidencial" propiedad de la otra parte, incluyendo, mas no limitando, el informar a sus empleados que la manejen, que dicha información es confidencial y que no deberá ser divulgada a terceras partes. Una vez la Parte Receptora utilice la información para el servicio que sea contratado, deberá devolver la Información Confidencial original a la Parte Reveladora y deberá destruir o ver que todas las copias que se encuentren en su posesión o en la de personas a quienes dicha Información haya sido revelada en concordancia con este Acuerdo sean destruidas. De igual forma, la Parte Reveladora podrá solicitar la devolución de la Información Confidencial en cualquier momento mediante la notificación por escrito a la Parte Receptora la cual contará con un término de treinta (30) días desde el recibo de la notificación para realizar la devolución total de la Información Confidencial y destruir las copias.'),
  P(b('CLÁUSULA VIGÉSIMA TERCERA: INCUMPLIMIENTO AL ACUERDO DE CONFIDENCIALIDAD. '),'Las partes convienen que en caso de que la Parte Receptora incumpla parcial o totalmente con las obligaciones a su cargo derivadas del presente contrato, la Parte que incumpla este acuerdo será responsable de los daños y perjuicios que dicho incumplimiento llegase a ocasionar a la Parte Reveladora.'),
  P(b('CLÁUSULA VIGÉSIMA CUARTA: COMPROMISO ANTICORRUPCIÓN. '),'EL CONTRATISTA, apoyará la acción del Estado Colombiano y particularmente de la ',E,', para fortalecer la transparencia y la responsabilidad de rendir cuentas, y en este contexto deberá asumir explícitamente los siguientes compromisos, sin perjuicio de su obligación de cumplir la Constitución y la Ley colombiana tales como: 1) EL CONTRATISTA se compromete a no ofrecer ni dar dádivas ni ninguna otra forma de halago a ningún funcionario público, ni pariente en cuarto grado de consanguinidad y segundo de afinidad y primero civil; 2) EL CONTRATISTA se compromete formalmente a no efectuar acuerdos o realizar actos o conductas que tengan por objeto la colusión en la ejecución del presente contrato.'),
  P(b('CLÁUSULA VIGÉSIMA QUINTA: MODIFICACIONES. '),'El presente contrato solo podrá modificarse por escrito firmado por ambas partes. Cualquier propuesta para su modificación deberá enviarse a los domicilios indicados al final de este contrato. El silencio a cualquier propuesta para modificación no tendrá el efecto de una aceptación.'),
  P(b('CLÁUSULA VIGÉSIMA SEXTA: LIQUIDACIÓN. '),'El presente contrato se liquidará dentro de los cuatro (4) meses siguientes a la fecha de terminación del contrato, o a la expedición del acto administrativo que ordene la terminación, o a la fecha del acuerdo que la disponga. Si no fuere posible realizar la liquidación de común acuerdo entre las partes, la ',E,', procederá a hacerlo unilateralmente mediante acto administrativo debidamente motivado.'),
  P(b('CLÁUSULA VIGÉSIMA SÉPTIMA: INHABILIDADES E INCOMPATIBILIDADES. '),'EL CONTRATISTA declara expresamente bajo la gravedad de juramento que no se halla incurso en las causales inhabilidades e incompatibilidades previstas en la ley.'),
  P(b('CLÁUSULA VIGÉSIMA OCTAVA: FUERZA MAYOR O CASO FORTUITO. '),'En caso de surgir hechos imprevistos a los cuales no se pueda resistir que impidan total o parcialmente el cumplimiento por una u otra parte de las obligaciones contraídas por el presente contrato, el plazo de cumplimiento de las obligaciones será prorrogado en uno igual al que duren tales circunstancias hasta que cesen las mismas, sin que por ello haya lugar a adicionar el contrato en su valor. La parte contratante que resulte afectada por tales hechos y que no pueda por ello cumplir con las obligaciones contractuales, deberá notificar por escrito a la otra parte, inmediatamente al surgimiento y a la terminación de dichas condiciones. Tal aviso deberá enviarse a la otra parte por comunicación escrita, dentro de los diez (10) días siguientes a partir de la fecha del comienzo de estas. Dentro de un plazo no mayor a veinte (20) días desde la fecha del aviso, la parte afectada por la fuerza mayor o caso fortuito deberá enviar una carta certificada anexando el documento de la autoridad competente en el cual se certifiquen las condiciones arriba mencionadas y las medidas tomadas para evitarlas, de ser ello procedente, excepto en el evento de que se trate de hechos notorios de público conocimiento. Durante el período en que persistan las circunstancias arriba mencionadas, las partes están obligadas a tomar las medidas necesarias para reducir los perjuicios provocados por las mismas. La parte afectada por tales circunstancias, que no le haya sido posible cumplir con las obligaciones contractuales, deberá informar periódicamente a la otra sobre el estado en que está transcurriendo la fuerza mayor o el caso fortuito. Si estas circunstancias duran más de siete (7) meses, las partes deberán ponerse de acuerdo con el fin de adecuar las condiciones del contrato a las nuevas situaciones que se presenten.'),
  P(b('CLÁUSULA VIGÉSIMA NOVENA: DOCUMENTOS. '),'Forman parte integrante del presente contrato los siguientes documentos: a) Requerimiento de Necesidad, Solicitud de CDP, Certificado de Disponibilidad Presupuestal CDP, Estudios Previos, Certificación de idoneidad. b) Verificación por parte la E.S.E Hospital Local ',M,' de los Antecedentes Disciplinarios en la página web de la Procuraduría General de La Nación, Boletín de Responsabilidad Fiscal en la página web de la Contraloría General de la República y los Antecedentes Judiciales en la Página Web de la Policía Nacional de Colombia (www.policia.gov.co) en el link (Consulta de Antecedentes Judiciales) y Registro Único Tributario RUT. c) Formato Único de Hoja de Vida del Departamento Administrativo de la Función Pública (Persona Natural) con todos sus anexos. d) Propuesta del contratista con sus anexos técnicos. e) Los demás documentos exigidos por la ley que directa o indirectamente se relacionen con este contrato y con la ejecución del mismo.'),
  P(b('CLÁUSULA TRIGÉSIMA: INDEMNIDAD. '),'EL CONTRATISTA, se obliga a mantener indemne a LA ',E,', de cualquier reclamación proveniente de terceros, debida o por el cumplimiento del presente contrato.'),
  P('Para constancia, el presente contrato se firma por las partes el día ',x(c.fsusL,'fecha de suscripción'),', en dos (02) ejemplares del mismo tenor y efecto legal, ',M,' – ',Dp,'.'),
  FIR([[b('CONTRATANTE')],[xb(AJ.gerente,'gerente')],['GERENTE E.S.E. '+M.toUpperCase()]],[[b('CONTRATISTA')],[xb(S.nombre,'nombre')],[x(c.doc,'documento')]]),
  NOTA('Proyectó y elaboró: ',AJ.proyecto)];

 case 'act':return[
  TIT('ACTA DE INICIO'),
  TBL([[b('CONTRATANTE'),E],[b('NIT'),AJ.nit],[b('CONTRATISTA'),[xb(S.nombre,'nombre')]],[b('NIT/C.C.'),[x(cc(S.ndoc),'documento')]],[b('No. DE CONTRATO'),[xb(c.num,'No. contrato')]],[b('OBJETO'),[obj]],[b('VALOR TOTAL'),[x(c.valL,'valor')]],[b('NÚMERO DE CDP'),['CDP # ',x(S.cdp,'No. CDP')]],[b('NÚMERO DE R.P.'),['R.P. # ',x(S.rp,'No. RP')]],[b('SUPERVISIÓN'),[x(c.sup.c,'supervisor'),' O QUIEN HAGA SUS VECES']],[b('PLAZO DE EJECUCIÓN'),[x(c.plazoL,'plazo')]]],[30,70]),
  P('En el Municipio de ',M,' (',Dp,'), se reunieron ',xb(c.sup.n,'supervisor'),', ',c.sup.c.charAt(0)+c.sup.c.slice(1).toLowerCase(),' en calidad de Supervisora y ',...persona,', que en adelante se denominará ',c.tr.al,', para la firma del Acta de Inicio del contrato No. ',xb(c.num,'No. contrato'),', con Objeto ',obj,' dentro de las instalaciones de la entidad, ubicada en el Municipio de ',M,' (',Dp,'). Para mayor constancia el presente documento se firma el día ',x(c.fsusL,'fecha de suscripción'),'.'),
  FIR([[xb(c.sup.n,'supervisor')],[c.sup.c],[b('SUPERVISOR')]],[[xb(S.nombre,'nombre')],[x(c.doc,'documento')],[b('CONTRATISTA')]])];
 }
 return[];
}
